-- CW Transportadora Web / PostgreSQL
CREATE TABLE IF NOT EXISTS manifestos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_arquivo TEXT, data_importacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS clientes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT, cnpj TEXT UNIQUE, cidade TEXT, uf TEXT, razao_social TEXT, fantasia TEXT, cpf TEXT, telefone TEXT, codigo TEXT, prioridade TEXT DEFAULT 'normal', criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS notas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, manifesto_id BIGINT REFERENCES manifestos(id) ON DELETE RESTRICT, chave_nfe TEXT UNIQUE, numero_cte TEXT, remetente_id BIGINT REFERENCES clientes(id) ON DELETE RESTRICT, destinatario_id BIGINT REFERENCES clientes(id) ON DELETE RESTRICT, valor_mercadoria NUMERIC(14,2) DEFAULT 0, valor_frete NUMERIC(14,2) DEFAULT 0, peso NUMERIC(14,3) DEFAULT 0, origem TEXT, destino TEXT, status TEXT DEFAULT 'Disponivel', criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, cubagem_m3 NUMERIC(14,3) DEFAULT 0, tipo_carga TEXT, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS caminhoes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, placa TEXT, modelo TEXT, motorista TEXT, capacidade_kg NUMERIC(14,3) DEFAULT 0, media_km_l NUMERIC(10,3) DEFAULT 0, status TEXT DEFAULT 'ATIVO', capacidade_m3 NUMERIC(14,3) DEFAULT 0, tipos_carga_permitidos TEXT, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS viagens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, caminhao_id BIGINT REFERENCES caminhoes(id) ON DELETE RESTRICT, data_saida TEXT, data_retorno TEXT, motorista TEXT, status TEXT, peso_total NUMERIC(14,3) DEFAULT 0, frete_total NUMERIC(14,2) DEFAULT 0, custo_total NUMERIC(14,2) DEFAULT 0, lucro_total NUMERIC(14,2) DEFAULT 0, custo_combustivel NUMERIC(14,2) DEFAULT 0, custo_pedagio NUMERIC(14,2) DEFAULT 0, custo_motorista NUMERIC(14,2) DEFAULT 0, custo_outros NUMERIC(14,2) DEFAULT 0, margem_percentual NUMERIC(10,3) DEFAULT 0, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS viagem_notas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, viagem_id BIGINT REFERENCES viagens(id) ON DELETE RESTRICT, nota_id BIGINT REFERENCES notas(id) ON DELETE RESTRICT, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE, UNIQUE(viagem_id, nota_id));
CREATE TABLE IF NOT EXISTS funcionarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL, cargo TEXT, status TEXT DEFAULT 'Ativo', salario NUMERIC(14,2) DEFAULT 0, telefone TEXT, data_admissao TEXT, vale_refeicao NUMERIC(14,2) DEFAULT 0, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS folha_funcionarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, funcionario_id BIGINT REFERENCES funcionarios(id) ON DELETE RESTRICT, mes TEXT, ano TEXT, salario NUMERIC(14,2) DEFAULT 0, vale_refeicao NUMERIC(14,2) DEFAULT 0, hora_extra NUMERIC(14,2) DEFAULT 0, outros NUMERIC(14,2) DEFAULT 0, total NUMERIC(14,2) DEFAULT 0, qtd_horas_extra NUMERIC(10,2) DEFAULT 0, valor_hora_extra NUMERIC(14,2) DEFAULT 0, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(funcionario_id, mes, ano));
CREATE TABLE IF NOT EXISTS operacoes_sp (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, data_operacao TEXT, nome_caminhao TEXT, placa TEXT, motorista TEXT, valor_notas NUMERIC(14,2) DEFAULT 0, frete_carreta NUMERIC(14,2) DEFAULT 0, pedagio_carreta NUMERIC(14,2) DEFAULT 0, outros_custos NUMERIC(14,2) DEFAULT 0, custo_total NUMERIC(14,2) DEFAULT 0, liquido NUMERIC(14,2) DEFAULT 0, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS contas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tipo TEXT, descricao TEXT, pessoa TEXT, categoria TEXT, valor NUMERIC(14,2) DEFAULT 0, vencimento TEXT, pagamento TEXT, status TEXT DEFAULT 'Pendente', observacao TEXT, viagem_id BIGINT REFERENCES viagens(id) ON DELETE SET NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS abastecimentos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, data_abastecimento TEXT, veiculo TEXT, motorista TEXT, km_atual NUMERIC(14,3) DEFAULT 0, litros NUMERIC(14,3) DEFAULT 0, valor_litro NUMERIC(14,4) DEFAULT 0, valor_total NUMERIC(14,2) DEFAULT 0, media_km_l NUMERIC(10,3) DEFAULT 0, custo_km NUMERIC(14,4) DEFAULT 0, posto TEXT, observacao TEXT, viagem_id BIGINT REFERENCES viagens(id) ON DELETE SET NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS manutencoes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, data_manutencao TEXT, veiculo TEXT, km_atual NUMERIC(14,3) DEFAULT 0, tipo TEXT, descricao TEXT, oficina TEXT, valor NUMERIC(14,2) DEFAULT 0, proxima_revisao_km NUMERIC(14,3) DEFAULT 0, status TEXT DEFAULT 'Pendente', observacao TEXT, viagem_id BIGINT REFERENCES viagens(id) ON DELETE SET NULL, sync_id TEXT UNIQUE, sincronizado BOOLEAN DEFAULT FALSE, atualizado_em TIMESTAMP, deletado BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS usuarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_completo TEXT NOT NULL, usuario TEXT NOT NULL UNIQUE, senha_hash TEXT NOT NULL, senha_salt TEXT NOT NULL, nivel_acesso TEXT NOT NULL DEFAULT 'comum', ativo BOOLEAN NOT NULL DEFAULT TRUE, deve_alterar_senha BOOLEAN NOT NULL DEFAULT FALSE, tentativas_falhas INTEGER NOT NULL DEFAULT 0, bloqueado_ate TEXT, ultimo_login TEXT, criado_por BIGINT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissoes_usuario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, modulo TEXT NOT NULL, pode_visualizar BOOLEAN DEFAULT TRUE, pode_criar BOOLEAN DEFAULT FALSE, pode_editar BOOLEAN DEFAULT FALSE, pode_excluir BOOLEAN DEFAULT FALSE, pode_exportar BOOLEAN DEFAULT FALSE, pode_sincronizar BOOLEAN DEFAULT FALSE, UNIQUE(usuario_id, modulo));
CREATE TABLE IF NOT EXISTS auditoria (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario_id BIGINT, usuario_nome TEXT, acao TEXT NOT NULL, modulo TEXT, registro_afetado TEXT, detalhes TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sync_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tabela TEXT, registro_id TEXT, operacao TEXT DEFAULT 'UPSERT', status TEXT DEFAULT 'PENDENTE', tentativas INTEGER DEFAULT 0, erro TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sincronizado_em TIMESTAMP, atualizado_em TIMESTAMP);
CREATE TABLE IF NOT EXISTS sync_estado (chave TEXT PRIMARY KEY, valor TEXT); CREATE TABLE IF NOT EXISTS sync_conflitos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tabela TEXT NOT NULL, registro_id TEXT NOT NULL, versao_local TEXT, versao_nuvem TEXT, decisao TEXT NOT NULL, detalhes TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_notas_status ON notas(status); CREATE INDEX IF NOT EXISTS idx_notas_manifesto ON notas(manifesto_id); CREATE INDEX IF NOT EXISTS idx_viagens_status ON viagens(status); CREATE INDEX IF NOT EXISTS idx_viagens_caminhao ON viagens(caminhao_id); CREATE INDEX IF NOT EXISTS idx_usuarios_usuario ON usuarios(usuario); CREATE INDEX IF NOT EXISTS idx_sync_log_status ON sync_log(status); CREATE INDEX IF NOT EXISTS idx_contas_viagem_id ON contas(viagem_id); CREATE INDEX IF NOT EXISTS idx_abastecimentos_viagem_id ON abastecimentos(viagem_id); CREATE INDEX IF NOT EXISTS idx_manutencoes_viagem_id ON manutencoes(viagem_id);
